using System.Collections.Generic;
namespace WorldWeaver
{
    public static class VillageKnowledge
    {
        public static List<KnowledgeDocument> Documents() => new List<KnowledgeDocument>
        {
            Doc("village", "Деревня", "Деревня называется Лунный Брод. Её основала картограф Аэлла в 417 году местного летоисчисления. Деревня стоит у реки Тихая."),
            Doc("crystal", "Кристалл", "Лечебный кристалл называется Зорецвет. Его добывают в шахте Семи Ветров. Обычная цена одного кристалла — 7 серебряных монет. Кристаллы хранятся в синем сундуке."),
            Doc("healer", "Лекарь", "Лекаря деревни зовут Эрина. Она принимает у западных ворот после заката. Для настоя от лихорадки Эрина использует растение серебролист."),
            Doc("merchant", "Торговец", "Торговца зовут Мирон. Его учителем был купец Берен. Мирон боится волков. Торговая лавка открывается на рассвете и закрывается при втором вечернем колоколе."),
            Doc("house", "Дом", "Дом торговца находится у восточного края рыночной площади. Над дверью висит медный полумесяц. После торговли Мирон обычно осматривает дом."),
            Doc("well", "Колодец", "Колодец называется Зеркальный. Его глубина — 18 локтей. Воду проверяет смотритель Тарен по понедельникам. Ключ от ворота колодца хранится у Эрины."),
            Doc("festival", "Праздник", "Праздник Урожая проводят 12 дня месяца Туманов. Символ праздника — белый фонарь. На площади исполняют песню Семь мостов."),
            Doc("bridge", "Мост", "Северный мост построен из красного камня. За проход берут 2 медные монеты. После наводнения проход разрешён только до полудня."),
            Doc("mine", "Шахта", "Вход в шахту Семи Ветров отмечен тремя синими полосами. Старший шахтёр — Дорин. Обвал произошёл в 429 году. Южная штольня закрыта."),
            Doc("library", "Библиотека", "Архив деревни расположен в башне Ив. Хранительницу зовут Селия. Самая старая книга называется Карта зимнего неба."),
            new KnowledgeDocument { Id = "guard-secret", Scope = "guard", Title = "Служебный пароль", Text = "Страж Лада знает пароль ночного караула: янтарная сова. Торговцу этот пароль неизвестен.", Kind = MemoryKind.StaticKnowledge }
        };
        private static KnowledgeDocument Doc(string id, string title, string text) => new KnowledgeDocument { Id = id, Title = title, Text = text, Scope = "merchant", Kind = MemoryKind.StaticKnowledge };
